/// One row of the release version inventory: the version claims found in
/// the top-level `Info.plist` of the artifact root (path `"."`) or of one
/// nested component. A missing declaration or an unreadable plist leaves the
/// affected field as an empty string rather than failing the scan.
public struct ReleaseVersionEntry: Codable, Equatable, Sendable {
    /// Path relative to the scanned artifact root; `"."` for the root itself.
    public let path: String
    /// Value of `CFBundleShortVersionString`, or `""` when absent/unreadable.
    public let shortVersion: String
    /// Value of `CFBundleVersion` (the build number), or `""` when absent.
    public let buildVersion: String

    public init(path: String, shortVersion: String, buildVersion: String) {
        self.path = path
        self.shortVersion = shortVersion
        self.buildVersion = buildVersion
    }
}

/// A component whose build number trails the highest comparable build.
public struct VersionLag: Codable, Equatable, Sendable {
    /// Path of the lagging entry, relative to the artifact root.
    public let path: String
    /// The entry's own build number.
    public let build: String
    /// The highest build number within the same segment-count group.
    public let referenceBuild: String

    public init(path: String, build: String, referenceBuild: String) {
        self.path = path
        self.build = build
        self.referenceBuild = referenceBuild
    }
}

/// Outcome of comparing the build numbers gathered by the version inventory.
/// `consistent == nil` encodes as an explicit JSON `null` when there is
/// nothing to compare (no nested components or no comparable build numbers).
public struct VersionConsistency: Codable, Equatable, Sendable {
    /// `false` when at least one entry lags, `true` when all comparable
    /// entries tie at the maximum, `nil` when comparison is not possible.
    public let consistent: Bool?
    /// Lagging entries sorted by relative path; empty when consistent.
    public let lagging: [VersionLag]

    public init(consistent: Bool?, lagging: [VersionLag]) {
        self.consistent = consistent
        self.lagging = lagging
    }
}

/// One residual item: a `.swift` source file, a `.dwarf` debug symbol, or a
/// directory named `Tests`. A `Tests` directory is itself a zero-byte entry;
/// instead of expanding its contents, `matchedBytes`/`matchedFileCount`
/// aggregate the regular-file hits beneath it.
public struct ResidualItem: Codable, Equatable, Sendable {
    /// Path relative to the scanned artifact root.
    public let path: String
    /// Bytes of the entry itself; always zero for a `Tests` directory.
    public let bytes: UInt64
    /// Aggregated bytes of matched regular files beneath a `Tests` directory.
    public let matchedBytes: UInt64?
    /// Aggregated number of matched regular files beneath a `Tests` directory.
    public let matchedFileCount: Int?

    public init(path: String, bytes: UInt64, matchedBytes: UInt64? = nil, matchedFileCount: Int? = nil) {
        self.path = path
        self.bytes = bytes
        self.matchedBytes = matchedBytes
        self.matchedFileCount = matchedFileCount
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(path, forKey: .path)
        try container.encode(bytes, forKey: .bytes)
        try container.encodeIfPresent(matchedBytes, forKey: .matchedBytes)
        try container.encodeIfPresent(matchedFileCount, forKey: .matchedFileCount)
    }

    private enum CodingKeys: String, CodingKey {
        case path, bytes, matchedBytes, matchedFileCount
    }
}

