    // item. The enumerator does not treat every component extension
    // as a package (e.g. `.framework` directories are descended
    // into), so containment is tracked explicitly: anything vended
    // below a component directory belongs to that component and is
    // never itself reported as a component.
    var componentLevels: [Int] = []

    while let child = enumerator.nextObject() as? URL {
        // Any failure reading a single item fails the whole scan: a
        // partial breakdown would not reconcile with the total.
