    /// Examines one enumerated item outside any nested component and records
    /// release residuals: `.swift` sources, `.dwarf` debug symbols, and
    /// directories named `Tests`. Inside an open `Tests` directory the hit
    /// types are aggregated onto that directory's single zero-byte entry
    /// instead of being expanded; a nested `Tests` is likewise folded in.
    private func collectResidual(for url: URL,
                                 values: URLResourceValues,
                                 relativePath relPath: String,
                                 level: Int,
                                 testsEnclosure: inout (level: Int, recordIndex: Int)?,
                                 records: inout [ResidualRecord]) {
        if testsEnclosure == nil, values.isDirectory == true, url.lastPathComponent == "Tests" {
            records.append(ResidualRecord(path: relPath, bytes: 0, isTests: true))
            testsEnclosure = (level, records.count - 1)
            return
        }

        if let tests = testsEnclosure {
            // Within a Tests directory only matched regular files feed the
            // aggregate; directories and non-matching files change nothing.
            if values.isRegularFile == true,
               ArtifactScanner.residualExtensions.contains(url.pathExtension.lowercased()) {
                let size = UInt64(max(values.fileSize ?? 0, 0))
                records[tests.recordIndex].matchedBytes += size
                records[tests.recordIndex].matchedFileCount += 1
            }
            return
        }

        guard values.isRegularFile == true,
              ArtifactScanner.residualExtensions.contains(url.pathExtension.lowercased()) else { return }
