    /// Sorts residual records by own bytes descending, then relative path
    /// ascending — an ordering fully determined by content.
    private static func residualItems(from records: [ResidualRecord]) -> [ResidualItem] {
        records.sorted { lhs, rhs in
            if lhs.bytes != rhs.bytes { return lhs.bytes > rhs.bytes }
            return lhs.path < rhs.path
        }.map { record in
            if record.isTests {
                return ResidualItem(
                    path: record.path,
                    bytes: 0,
                    matchedBytes: record.matchedBytes,
                    matchedFileCount: record.matchedFileCount
                )
            }
            return ResidualItem(path: record.path, bytes: record.bytes)
        }
