    /// Builds the version rows for the root (`"."`) and every nested
    /// component's top-level `Info.plist`. The top-level plist follows the
    /// bundle layout (`Contents/Info.plist` for applications, `Info.plist`
    /// beside the package for frameworks/bundles); deeper nested bundles are
    /// never read. Missing declarations and unreadable plists yield empty
    /// fields rather than failing the scan.
    private func versionInventory(root: URL,
                                  rootKind: ArtifactKind,
                                  components: [ArtifactComponent],
                                  locations: [String: URL]) -> [ReleaseVersionEntry] {
        var rows: [ReleaseVersionEntry] = [
            versionEntry(path: ".", plist: ArtifactScanner.infoPlist(for: root, kind: rootKind))
        ]
        for component in components {
            // pkg/dmg components are opaque files; their top-level plist is
            // never readable, so the row exists with empty fields.
            let plist = locations[component.path]
                .map { ArtifactScanner.infoPlist(for: $0, kind: component.kind) }
            rows.append(versionEntry(path: component.path, plist: plist))
