    private static func infoPlist(for location: URL, kind: ArtifactKind) -> URL? {
        switch kind {
        case .application:
            return location.appendingPathComponent("Contents").appendingPathComponent("Info.plist")
        case .framework, .bundle:
            return location.appendingPathComponent("Info.plist")
        case .directory:
            return location.appendingPathComponent("Info.plist")
        case .package, .diskImage, .file:
            return nil
        }
    }

    private func versionEntry(path: String, plist: URL?) -> ReleaseVersionEntry {
        guard let plist,
              let data = try? Data(contentsOf: plist),
              let object = try? PropertyListSerialization.propertyList(from: data, options: [], format: nil),
              let dictionary = object as? [String: Any] else {
            return ReleaseVersionEntry(path: path, shortVersion: "", buildVersion: "")
        }
        let short = dictionary["CFBundleShortVersionString"] as? String ?? ""
        let build = dictionary["CFBundleVersion"] as? String ?? ""
        return ReleaseVersionEntry(path: path, shortVersion: short, buildVersion: build)
    }

    /// Compares build numbers per the release contract: only period-separated
    /// non-negative decimal integers with the same segment count are compared
    /// segment by segment; the highest tuple in each segment-count group is
    /// that group's reference, and anything below it is reported lagging.
    /// Missing/unparseable builds do not participate. Returns `nil` (encoded
    /// null) when there are no nested components or no comparable builds.
    private static func consistency(for rows: [ReleaseVersionEntry],
                                    hasComponents: Bool) -> VersionConsistency? {
        guard hasComponents else { return VersionConsistency(consistent: nil, lagging: []) }

        // One parsed tuple per row whose build is comparable.
        let comparable = rows.compactMap { row -> (path: String, raw: String, segments: [UInt64])? in
            guard let segments = parseBuild(row.buildVersion) else { return nil }
            return (row.path, row.buildVersion, segments)
        }
        guard !comparable.isEmpty else { return VersionConsistency(consistent: nil, lagging: []) }

        // Reference per segment-count group. Dictionary iteration order never
        // touches the output: lagging rows are sorted by path afterwards.
        var references: [Int: [UInt64]] = [:]
        for entry in comparable {
            let count = entry.segments.count
            if let existing = references[count] {
                if segmentwiseLess(existing, entry.segments) {
                    references[count] = entry.segments
                }
            } else {
                references[count] = entry.segments
            }
        }

        var lagging: [VersionLag] = []
        for entry in comparable {
            guard let reference = references[entry.segments.count],
                  segmentwiseLess(entry.segments, reference) else { continue }
            lagging.append(VersionLag(
                path: entry.path,
                build: entry.raw,
                referenceBuild: reference.map(String.init).joined(separator: ".")
            ))
        }
        lagging.sort { $0.path < $1.path }
        return VersionConsistency(consistent: lagging.isEmpty, lagging: lagging)
    }

    /// Parses `digits(.digits)*` with every segment a non-negative decimal
    /// integer; anything else (empty, signs, leading/trailing dots, other
    /// punctuation) is not a comparable build and returns nil.
    private static func parseBuild(_ raw: String) -> [UInt64]? {
        guard !raw.isEmpty else { return nil }
        let parts = raw.split(separator: ".", omittingEmptySubsequences: false)
        guard !parts.isEmpty else { return nil }
        return parts.map { part -> UInt64? in
            guard !part.isEmpty, part.allSatisfy({ $0.isNumber }) else { return nil }
            return UInt64(part)
        }
        .reduce(into: [UInt64]?.some([])) { acc, segment in
            guard let acc, let segment else { acc = nil; return }
            acc?.append(segment)
        }
    }

    private static func segmentwiseLess(_ lhs: [UInt64], _ rhs: [UInt64]) -> Bool {
        for (l, r) in zip(lhs, rhs) where l != r { return l < r }
        return false
    }
}

