/// Mutable accumulation form of `ResidualItem` while the traversal runs.
private struct ResidualRecord {
    var path: String
    var bytes: UInt64
    var isTests: Bool
    var matchedBytes: UInt64 = 0
    var matchedFileCount: Int = 0
}

/// Examines one enumerated item outside any nested component and records
/// release residuals: `.swift` sources, `.dwarf` debug symbols, and
/// directories named `Tests`. Inside an open `Tests` directory the hit
/// types are aggregated onto that directory's single zero-byte entry
/// instead of being expanded; a nested `Tests` is likewise folded in.
private func collectResidual(for url: URL,
                             values: URLResourceValues,
                             relativePath relPath: String,
                             level: Int,
                             testsEnclosure: inout (level: Int, recordIndex: Int)?,
                             records: inout [ResidualRecord]) {
    if testsEnclosure == nil, values.isDirectory == true, url.lastPathComponent == "Tests" {
        records.append(ResidualRecord(path: relPath, bytes: 0, isTests: true))
        testsEnclosure = (level, records.count - 1)
        return
    }

    if let tests = testsEnclosure {
        // Within a Tests directory only matched regular files feed the
        // aggregate; directories and non-matching files change nothing.
        if values.isRegularFile == true,
           ArtifactScanner.residualExtensions.contains(url.pathExtension.lowercased()) {
            let size = UInt64(max(values.fileSize ?? 0, 0))
            records[tests.recordIndex].matchedBytes += size
            records[tests.recordIndex].matchedFileCount += 1
        }
        return
    }

    guard values.isRegularFile == true,
          ArtifactScanner.residualExtensions.contains(url.pathExtension.lowercased()) else { return }
    records.append(ResidualRecord(
        path: relPath,
        bytes: UInt64(max(values.fileSize ?? 0, 0)),
        isTests: false
    ))
}

private static let residualExtensions: Set<String> = ["swift", "dwarf"]

/// Sorts residual records by own bytes descending, then relative path
/// ascending — an ordering fully determined by content.
private static func residualItems(from records: [ResidualRecord]) -> [ResidualItem] {
    records.sorted { lhs, rhs in
        if lhs.bytes != rhs.bytes { return lhs.bytes > rhs.bytes }
        return lhs.path < rhs.path
    }.map { record in
        if record.isTests {
            return ResidualItem(
                path: record.path,
                bytes: 0,
                matchedBytes: record.matchedBytes,
                matchedFileCount: record.matchedFileCount
            )
        }
        return ResidualItem(path: record.path, bytes: record.bytes)
    }
}

/// Builds the version rows for the root (`"."`) and every nested
/// component's top-level `Info.plist`. The top-level plist follows the
/// bundle layout (`Contents/Info.plist` for applications, `Info.plist`
/// beside the package for frameworks/bundles); deeper nested bundles are
/// never read. Missing declarations and unreadable plists yield empty
/// fields rather than failing the scan.
private func versionInventory(root: URL,
                              rootKind: ArtifactKind,
                              components: [ArtifactComponent],
                              locations: [String: URL]) -> [ReleaseVersionEntry] {
    var rows: [ReleaseVersionEntry] = [
        versionEntry(path: ".", plist: ArtifactScanner.infoPlist(for: root, kind: rootKind))
    ]
    for component in components {
        // pkg/dmg components are opaque files with no top-level plist
        // (`infoPlist` returns nil for those kinds); every other
        // component's row reads its own bundle-layout plist.
        let plist = locations[component.path]
            .flatMap { ArtifactScanner.infoPlist(for: $0, kind: component.kind) }
        rows.append(versionEntry(path: component.path, plist: plist))
    }
    return rows
}

/// URL of the top-level `Info.plist` for an item of the given kind.
private static func infoPlist(for location: URL, kind: ArtifactKind) -> URL? {
    switch kind {
    case .application:
        return location.appendingPathComponent("Contents").appendingPathComponent("Info.plist")
    case .framework, .bundle:
        return location.appendingPathComponent("Info.plist")
    case .directory:
        return location.appendingPathComponent("Info.plist")
    case .package, .diskImage, .file:
        return nil
    }
}

private func versionEntry(path: String, plist: URL?) -> ReleaseVersionEntry {
    guard let plist,
          let data = try? Data(contentsOf: plist),
          let object = try? PropertyListSerialization.propertyList(from: data, options: [], format: nil),
          let dictionary = object as? [String: Any] else {
        return ReleaseVersionEntry(path: path, shortVersion: "", buildVersion: "")
    }
    let short = ArtifactScanner.plistString(dictionary["CFBundleShortVersionString"])
    let build = ArtifactScanner.plistString(dictionary["CFBundleVersion"])
    return ReleaseVersionEntry(path: path, shortVersion: short, buildVersion: build)
