    /// Parses `digits(.digits)*` with every segment a non-negative decimal
    /// integer; anything else (empty, signs, leading/trailing/empty
    /// segments, non-digit characters) is not a comparable build.
    private static func parseBuild(_ raw: String) -> [UInt64]? {
        let parts = raw.split(separator: ".", omittingEmptySubsequences: false)
        guard !raw.isEmpty, !parts.isEmpty else { return nil }
        var segments: [UInt64] = []
        segments.reserveCapacity(parts.count)
